"""Data Transfer Objects (DTOs) for orders, fills, and corporate actions.

All DTOs are frozen slotted dataclasses with zero I/O, ensuring immutability
across process boundaries and enabling safe caching and ledger hashing.
"""
from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime

from ta_core.enums import Action, Arm, Horizon, Side, Sleeve

__all__ = ["CorporateAction", "Fill", "OrderIntent"]


@dataclass(frozen=True, slots=True)
class OrderIntent:
    """Intended order generated by strategy before risk gating or broker fill."""

    rec_id: str
    symbol: str
    industry: str
    d: date
    side: Side
    action: Action
    sleeve: Sleeve
    horizon: Horizon
    qty: int
    entry_lo: float
    entry_hi: float
    stop: float
    target: float
    arm: Arm = Arm.DETERMINISTIC


@dataclass(frozen=True, slots=True)
class Fill:
    """Execution report from paper broker or exchange."""

    order_id: str
    symbol: str
    d: date
    side: Side
    qty: int
    price: float
    gross_notional: float
    costs_rupees: float
    net_notional: float
    slippage_bps: float = 0.0
    reason: str = ""


@dataclass(frozen=True, slots=True)
class CorporateAction:
    """Point-in-time corporate action record (split, bonus, dividend)."""

    symbol: str
    ex_date: date
    action_type: str  # "SPLIT" | "BONUS" | "DIVIDEND"
    ratio_from: float
    ratio_to: float
    adj_factor: float
    knowledge_time: datetime
    dividend: float = 0.0
